:\n+            httpGet:\n+              path: /healthz\n+              port: http\n+            periodSeconds: 5\ndiff --git a/service.yaml b/service.yaml\nnew file mode 100644\nindex 0000000..eaa45ee\n--- /dev/null\n+++ b/service.yaml\n@@ -0,0 +1,14 @@\n+apiVersion: v1\n+kind: Service\n+metadata:\n+  name: s1-app\n+  namespace: demo-s1\n+  labels:\n+    app.kubernetes.io/name: s1-app\n+spec:\n+  selector:\n+    app.kubernetes.io/name: s1-app\n+  ports:\n+    - name: http\n+      port: 80\n+      targetPort: http",
